#!/usr/bin/env python3
"""Готовлю числа финмодели из CSV эксперта А + строю текст раздела §3.4"""
import csv
from pathlib import Path

# Цены регионов:
CITIES = [
    ('Москва', 1),
    ('Краснодар', 3),
    ('Санкт-Петербург', 4),
    ('Новосибирск', 7),
    ('Екатеринбург', 12),
]

def num(s):
    s = (s or '').strip().replace(' ', '').replace('\xa0', '')
    try: return int(s)
    except:
        try: return float(s)
        except: return 0

rows = []
with open('/home/ubuntu/.cursor/projects/workspace/uploads/kicksharing_v2_b578.csv','r',encoding='utf-8') as f:
    for r in csv.reader(f, delimiter=';'):
        rows.append(r)

city_data = {}
for name, rid in CITIES:
    r = None
    for rr in rows[3:]:
        if rr and rr[0].strip()==str(rid):
            r = rr
            break
    assert r is not None, f"Region id={rid} ({name}) NOT FOUND in CSV"
    rev24 = sum(num(r[i]) for i in range(1,5))
    rev24_9m = sum(num(r[i]) for i in range(1,4))
    rev25_9m = sum(num(r[i]) for i in range(5,8))
    fleet24 = num(r[8])
    fleet25 = num(r[9])
    active24 = num(r[17])
    active25_9m = num(r[18])
    trips24 = sum(num(r[i]) for i in range(21,25))
    trips24_9m = sum(num(r[i]) for i in range(21,24))
    trips25_9m = sum(num(r[i]) for i in range(25,28))
    yoy_rev = (rev25_9m/rev24_9m-1)*100 if rev24_9m else 0
    yoy_trips = (trips25_9m/trips24_9m-1)*100 if trips24_9m else 0
    avg_check = rev24/trips24 if trips24 else 0
    util24 = trips24/fleet24 if fleet24 else 0
    city_data[name] = dict(
        rev24=rev24, rev24_9m=rev24_9m, rev25_9m=rev25_9m,
        fleet24=fleet24, fleet25=fleet25,
        active24=active24, trips24=trips24,
        trips24_9m=trips24_9m, trips25_9m=trips25_9m,
        yoy_rev=yoy_rev, yoy_trips=yoy_trips,
        avg_check=avg_check, util24=util24,
    )

# Сумма по портфелю
def total_24():
    return sum(d['rev24'] for d in city_data.values())
total_rev24 = total_24()
print(f"Total rev24 (5 cities): {total_rev24/1e9:.2f} млрд руб")

# Сумма по всему Юрент
total_rev24_all = 0
total_trips24_all = 0
total_fleet24_all = 0
for rr in rows[3:]:
    if not rr or not rr[0].strip().isdigit(): continue
    total_rev24_all += sum(num(rr[i]) for i in range(1,5))
    total_trips24_all += sum(num(rr[i]) for i in range(21,25))
    total_fleet24_all += num(rr[8])
print(f"Total Юрент rev24: {total_rev24_all/1e9:.2f} млрд")
print(f"Total Юрент fleet24: {total_fleet24_all:,}")
print(f"Доля 5 городов: {total_rev24/total_rev24_all*100:.1f}%")

# Печатаем сводку
for name, _ in CITIES:
    d = city_data[name]
    print(f"\n{name}:")
    print(f"  Выручка 2024: {d['rev24']/1e6:.1f} млн")
    print(f"  YoY 9м25/9м24: выручка {d['yoy_rev']:+.1f}%, поездки {d['yoy_trips']:+.1f}%")
    print(f"  Парк: {d['fleet24']} → {d['fleet25']}")
    print(f"  Средний чек: {d['avg_check']:.1f} руб")
    print(f"  Утилизация 2024: {d['util24']:.0f}")

# ============================================================
# СОБСТВЕННО ТЕКСТ ФИНМОДЕЛИ
